-- Hollowmere gains the Hollow Throne (level 2) and Cindervault the sealed Crucible (level 2): the boss
-- level, a gated stair down from the level above (quest unlock), the boss spawn and lights.
update eldervale_private.underground_areas set data=data||jsonb_build_object('lair',$j$"hollow_king"$j$::jsonb,
  'levels',data->'levels'||coalesce((select jsonb_agg(l) from jsonb_array_elements($j$[{"level":2,"name":"Hollow Throne","rooms":[{"id":"vestibule","x":0,"z":0,"rx":6,"rz":5},{"id":"throne","x":30,"z":0,"rx":16,"rz":13}],"tunnels":[{"width":3.4,"points":[[0,0],[30,0]]}]}]$j$::jsonb) l where not exists(select 1 from jsonb_array_elements(data->'levels') o where o->'level'=l->'level')),'[]'),
  'links',coalesce(data->'links','[]')||coalesce((select jsonb_agg(l) from jsonb_array_elements($j$[{"id":"throne_stair","kind":"stairs","level":1,"x":46,"z":26,"to":{"level":2,"x":1.5,"z":0},"requires":{"unlock":"lair:hollow_throne","gate":true}}]$j$::jsonb) l where not exists(select 1 from jsonb_array_elements(coalesce(data->'links','[]')) o where o->>'id'=l->>'id')),'[]'),
  'spawns',coalesce(data->'spawns','[]')||coalesce((select jsonb_agg(s) from jsonb_array_elements($j$[{"id":"hollow_king","roster":"hollow_king","count":1,"level":2,"room":"throne","roam":2,"respawn":30}]$j$::jsonb) s where not exists(select 1 from jsonb_array_elements(coalesce(data->'spawns','[]')) o where o->>'id'=s->>'id')),'[]'),
  'lights',coalesce(data->'lights','[]')||(case when exists(select 1 from jsonb_array_elements(data->'levels') o where (o->>'level')::integer=2) then '[]'::jsonb else $j$[{"level":2,"x":3,"z":3,"kind":"brazier"},{"level":2,"x":20,"z":-8,"kind":"crystal"},{"level":2,"x":20,"z":8,"kind":"crystal"},{"level":2,"x":42,"z":0,"kind":"brazier"}]$j$::jsonb end),
  'reserved',coalesce((select jsonb_agg(r) from jsonb_array_elements(coalesce(data->'reserved','[]')) r where not ($j$[]$j$::jsonb ? (r->>'room'))),'[]'))
 where id='hollowmere_undercroft' and not (data ? 'lair');
update eldervale_private.underground_areas set data=data||jsonb_build_object('lair',$j$"ashen_colossus"$j$::jsonb,
  'levels',data->'levels'||coalesce((select jsonb_agg(l) from jsonb_array_elements($j$[{"level":2,"name":"The Crucible","rooms":[{"id":"vestibule","x":0,"z":0,"rx":6,"rz":5},{"id":"crucible","x":32,"z":0,"rx":17,"rz":14}],"tunnels":[{"width":3.4,"points":[[0,0],[32,0]]}]}]$j$::jsonb) l where not exists(select 1 from jsonb_array_elements(data->'levels') o where o->'level'=l->'level')),'[]'),
  'links',coalesce(data->'links','[]')||coalesce((select jsonb_agg(l) from jsonb_array_elements($j$[{"id":"crucible_stair","kind":"stairs","level":1,"x":66,"z":42,"to":{"level":2,"x":1.5,"z":0},"requires":{"unlock":"lair:cindervault_crucible","gate":true}}]$j$::jsonb) l where not exists(select 1 from jsonb_array_elements(coalesce(data->'links','[]')) o where o->>'id'=l->>'id')),'[]'),
  'spawns',coalesce(data->'spawns','[]')||coalesce((select jsonb_agg(s) from jsonb_array_elements($j$[{"id":"colossus","roster":"ashen_colossus","count":1,"level":2,"room":"crucible","roam":2,"respawn":30}]$j$::jsonb) s where not exists(select 1 from jsonb_array_elements(coalesce(data->'spawns','[]')) o where o->>'id'=s->>'id')),'[]'),
  'lights',coalesce(data->'lights','[]')||(case when exists(select 1 from jsonb_array_elements(data->'levels') o where (o->>'level')::integer=2) then '[]'::jsonb else $j$[{"level":2,"x":3,"z":3,"kind":"brazier"},{"level":2,"x":20,"z":-10,"kind":"lava"},{"level":2,"x":20,"z":10,"kind":"lava"},{"level":2,"x":46,"z":-10,"kind":"lava"},{"level":2,"x":46,"z":10,"kind":"lava"}]$j$::jsonb end),
  'reserved',coalesce((select jsonb_agg(r) from jsonb_array_elements(coalesce(data->'reserved','[]')) r where not ($j$["crucible"]$j$::jsonb ? (r->>'room'))),'[]'))
 where id='cindervault_depths' and not (data ? 'lair');

select eldervale_private.underground_sync(id) from eldervale_private.underground_areas where id in ('bloodtusk_warhall','gloomweb_nest','rimecoil_cavern','wyrmhold','hollowmere_undercroft','cindervault_depths') order by id;

